CREATE TRIGGER `trg_validate_kanji_answer`
BEFORE INSERT ON `kanji_practice_answers`
FOR EACH ROW
WHEN NOT EXISTS (
	SELECT 1
	FROM `kanji_practice_sessions` AS session
	WHERE session.id = NEW.session_id
	  AND session.learner_id = NEW.learner_id
	  AND session.status = 'active'
	  AND session.turn = NEW.turn
	  AND session.current_kanji_id = NEW.kanji_id
)
BEGIN
	SELECT RAISE(ABORT, 'stale_kanji_answer');
END;
